// DecodeError identifies and decodes a declared custom error.
func (c *IValidatorShareBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("BackingLotNotFound()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeBackingLotNotFoundError(raw)
	}
	if definition, err := c.customError("BackingLotTooSmall()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeBackingLotTooSmallError(raw)
	}
	if definition, err := c.customError("DifferentValidators()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeDifferentValidatorsError(raw)
	}
	if definition, err := c.customError("DustBackingLot()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeDustBackingLotError(raw)
	}
	if definition, err := c.customError("InsufficientBacking()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInsufficientBackingError(raw)
	}
	if definition, err := c.customError("InvalidLotLimit()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidLotLimitError(raw)
	}
	if definition, err := c.customError("InvalidShareTokenId()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeInvalidShareTokenIdError(raw)
	}
	if definition, err := c.customError("NotPositionOwner()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotPositionOwnerError(raw)
	}
	if definition, err := c.customError("RedemptionWorkLimit()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeRedemptionWorkLimitError(raw)
	}
	if definition, err := c.customError("RepayExceedsBacking()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeRepayExceedsBackingError(raw)
	}
	if definition, err := c.customError("ZeroAddress()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroAddressError(raw)
	}
	if definition, err := c.customError("ZeroShareAmount()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroShareAmountError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
